private static boolean isWriteLimitReached(Throwable t, int depth) {
    if (t == null) {
        return false;
    }
    if (depth > MAX_DEPTH) {
        return false;
    }
    if (t instanceof WriteLimitReachedException) {
        return true;
    } else {
        return isWriteLimitReached(t.getCause(), depth + 1);
    }
}
